package jumphost

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	// SignInIAM signs in with AWS IAM tokens generated by acme.
	SignInIAM = "iam"
	// SignInPassword signs in with a password typed at every connection (never saved).
	SignInPassword = "password"

	prefsFileVersion = 1
)

// ConnectionPrefs are the Connect step choices remembered for one database (AWS account, region
// and instance name, which RDS keeps unique).
// Passwords are never part of them.
type ConnectionPrefs struct {
	UpdatedAt time.Time `json:"updated_at"`
	DBUser    string    `json:"db_user,omitempty"`
	// SignIn is SignInIAM or SignInPassword; empty reads as SignInIAM.
	SignIn         string `json:"sign_in,omitempty"`
	LocalPort      int    `json:"local_port,omitempty"`
	MCPAllowWrites bool   `json:"mcp_allow_writes"`
}

// Passwordless reports whether the connection signs in with AWS IAM tokens rather than a typed password.
func (p ConnectionPrefs) Passwordless() bool {
	return p.SignIn != SignInPassword
}

// prefsFile is the JSON document of a PrefsStore.
type prefsFile struct {
	// Connections is keyed by "<account>/<region>/<database>" (see prefsKey).
	Connections map[string]ConnectionPrefs `json:"connections"`
	Version     int                        `json:"version"`
}

// PrefsStore keeps ConnectionPrefs in a JSON file, one entry per database. Entries are keyed by
// AWS account rather than profile: several profiles may reach one account, and profile names are
// local to each machine.
type PrefsStore struct {
	now  func() time.Time
	path string
}

// NewPrefsStore stores preferences in path, created on the first save.
func NewPrefsStore(path string) *PrefsStore {
	return &PrefsStore{path: path, now: time.Now}
}

// DatabaseRef identifies an RDS instance across AWS accounts.
type DatabaseRef struct {
	Account string
	Region  string
	Name    string
}

func (d DatabaseRef) key() string {
	return strings.TrimSpace(d.Account) + "/" + strings.TrimSpace(d.Region) + "/" + strings.TrimSpace(d.Name)
}

func (d DatabaseRef) complete() bool {
	return strings.TrimSpace(d.Account) != "" && strings.TrimSpace(d.Region) != "" && strings.TrimSpace(d.Name) != ""
}

// Load returns the preferences saved for db. A missing or unreadable file reads as no
// preferences: they are a convenience and never block a connection.
func (s *PrefsStore) Load(db DatabaseRef) (ConnectionPrefs, bool) {
	if !db.complete() {
		return ConnectionPrefs{}, false
	}
	file, err := s.read()
	if err != nil {
		return ConnectionPrefs{}, false
	}
	prefs, ok := file.Connections[db.key()]
	return prefs, ok
}

// Save records prefs for db, keeping the entries of other databases.
func (s *PrefsStore) Save(db DatabaseRef, prefs ConnectionPrefs) error {
	if !db.complete() {
		return errors.New("connection preferences need an AWS account, a region and a database")
	}
	file, err := s.read()
	if err != nil {
		// Rewriting would drop every entry of a file we cannot parse.
		return err
	}
	prefs.UpdatedAt = s.now().UTC()
	file.Connections[db.key()] = prefs
	file.Version = prefsFileVersion

	data, err := json.MarshalIndent(file, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to encode connection preferences: %w", err)
	}
	return writePrefsAtomic(s.path, append(data, '\n'))
}

// read parses the file; a missing file is an empty document.
func (s *PrefsStore) read() (prefsFile, error) {
	file := prefsFile{Connections: map[string]ConnectionPrefs{}}
	data, err := os.ReadFile(s.path)
	if errors.Is(err, os.ErrNotExist) {
		return file, nil
	}
	if err != nil {
		return file, fmt.Errorf("failed to read connection preferences: %w", err)
	}
	if err := json.Unmarshal(data, &file); err != nil {
		return file, fmt.Errorf("failed to parse connection preferences %s: %w", s.path, err)
	}
	if file.Connections == nil {
		file.Connections = map[string]ConnectionPrefs{}
	}
	return file, nil
}

// writePrefsAtomic replaces path through a temporary file, so a crash never leaves it half written.
func writePrefsAtomic(path string, data []byte) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return fmt.Errorf("failed to create %s: %w", dir, err)
	}
	tmp, err := os.CreateTemp(dir, ".connections-*.json")
	if err != nil {
		return fmt.Errorf("failed to save connection preferences: %w", err)
	}
	defer func() { _ = os.Remove(tmp.Name()) }()

	_, writeErr := tmp.Write(data)
	closeErr := tmp.Close()
	if err := errors.Join(writeErr, closeErr, os.Chmod(tmp.Name(), 0o600)); err != nil {
		return fmt.Errorf("failed to save connection preferences: %w", err)
	}
	if err := os.Rename(tmp.Name(), path); err != nil {
		return fmt.Errorf("failed to save connection preferences: %w", err)
	}
	return nil
}
